  await b.setViewportSize({width:390,height:844});await b.screenshot({path:'artifacts/docx-marks-mobile.png'});expect(await b.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth)).toBe(true);
  await b.getByRole('button',{name:'导出 DOCX 正文副本',exact:true}).click();
  const exportDialog=b.getByRole('dialog',{name:'导出 DOCX 正文兼容副本'});await expect(exportDialog).toContainText('复杂表格、页眉页脚');
  await b.setViewportSize({width:390,height:844});expect(await exportDialog.evaluate(element=>element.scrollWidth<=element.clientWidth)).toBe(true);await b.screenshot({path:'artifacts/docx-export-mobile.png'});
  const download=b.waitForEvent('download');await exportDialog.getByRole('button',{name:'确认导出正文副本',exact:true}).click();const downloaded=await download;
  expect(downloaded.suggestedFilename()).toBe('正文-正文副本.docx');
  const {readFile}=await import('node:fs/promises');const exported=await readFile((await downloaded.path())!);
  const {unzipSync,strFromU8}=await import('fflate');const parts=unzipSync(exported);expect(strFromU8(parts['word/document.xml'])).toContain('第二段');expect(strFromU8(parts['word/document.xml'])).toContain('<w:b w:val="1"/>');expect(strFromU8(parts['word/document.xml'])).toContain('<w:i w:val="1"/>');expect(strFromU8(parts['word/document.xml'])).toContain('<w:pStyle w:val="Heading2"/>');expect(strFromU8(parts['word/styles.xml'])).toContain('heading 2');expect(strFromU8(parts['word/numbering.xml'])).toContain('decimal');expect(strFromU8(parts['word/_rels/document.xml.rels'])).toContain('Target="https://example.com/?a=1&amp;b=2"');expect(strFromU8(parts['word/document.xml'])).toContain('第二列表项');expect(strFromU8(parts['word/document.xml'])).toContain('<w:jc w:val="center"/>');expect(strFromU8(parts['word/document.xml'])).toContain('w:left="720"');expect(strFromU8(parts['word/document.xml'])).toContain('w:right="360"');expect(strFromU8(parts['word/document.xml'])).toContain('w:hanging="720"');
  const imported=await first.request.post(baseURL+'/api/cloud/office-import?'+new URLSearchParams({workspace:space.id,name:'重开.docx'}),{data:exported,headers:{'Content-Type':'application/octet-stream'}});expect(imported.ok()).toBe(true);
