test('TXT 逻辑行号、字符位置、长文本滚动与本机换行设置',async({browser,baseURL})=>{
 const first=await browser.newContext(),second=await browser.newContext();
 try{
  const owner=await officeAccount(first,baseURL!,'owner','owner'+officeAccountSuffix+'@example.com'),member=await officeAccount(second,baseURL!,'member','member'+officeAccountSuffix+'@example.com');
  const space=await(await first.request.post(baseURL+'/api/cloud/workspaces',{data:{name:'TXT 行号'}})).json(),invite=await(await first.request.post(baseURL+'/api/cloud/invite?workspace='+space.id,{data:{email:'member'+officeAccountSuffix+'@example.com'}})).json();await second.request.post(baseURL+'/api/cloud/accept',{data:{token:invite.token}});expect(owner.id).not.toBe(member.id);
  const resource=await(await first.request.post(baseURL+'/api/cloud/office-resources?workspace='+space.id,{data:{kind:'text',name:'行号.txt',mime:'text/plain',sourceFormat:'txt'}})).json();
  const a=await first.newPage(),b=await second.newPage();for(const page of [a,b]){await page.goto(baseURL!+'/#workspace='+space.id);await page.getByRole('navigation',{name:'文档列表'}).getByRole('button',{name:'行号.txt',exact:true}).click();}
  const ta=a.getByRole('textbox',{name:'行号.txt',exact:true}),tb=b.getByRole('textbox',{name:'行号.txt',exact:true}),status=a.getByRole('status',{name:'文本位置',exact:true});await expect(status).toContainText('共 1 行');await ta.fill('甲😀\n\n末\n');await expect(b.getByRole('status',{name:'文本位置',exact:true})).toContainText('共 4 行');await ta.evaluate(el=>(el as HTMLTextAreaElement).setSelectionRange(1,3));await expect(status).toContainText('第 1 行，第 3 列');await expect(status).toContainText('已选 1 个字符');
  await ta.evaluate(el=>(el as HTMLTextAreaElement).setSelectionRange(0,3,'backward'));await expect(status).toContainText('第 1 行，第 1 列');
  const large=Array.from({length:1000},(_,i)=>`第 ${i+1} 行 中文😀`).join('\n');await ta.fill(large);await expect(tb).toHaveValue(large);await ta.evaluate(el=>{el.scrollTop=5000;el.dispatchEvent(new Event('scroll'));});await expect.poll(()=>a.locator('.text-line-gutter span').first().getAttribute('data-line')).not.toBe('1');expect(await a.locator('.text-line-gutter span').count()).toBeLessThan(50);
  await expect.poll(()=>a.locator('.text-line-gutter span').first().evaluate(el=>{const area=document.querySelector<HTMLTextAreaElement>('.text-document-input')!,style=getComputedStyle(area),line=Number(el.getAttribute('data-line'));return Math.abs(parseFloat((el as HTMLElement).style.top)-(parseFloat(style.paddingTop)+(line-1)*parseFloat(style.lineHeight)-area.scrollTop))<0.6;})).toBe(true);
  await tb.fill('远端\n'+large);await expect(status).toContainText('共 1001 行');
  await a.getByRole('button',{name:'文本格式',exact:true}).click();await a.getByLabel('显示行号',{exact:true}).uncheck();await expect(a.locator('.text-line-gutter')).toHaveCount(0);await a.getByLabel('显示行号',{exact:true}).check();await expect(a.locator('.text-line-gutter')).toBeVisible();await a.getByLabel('自动换行',{exact:true}).check();await expect(ta).toHaveAttribute('wrap','soft');await expect(a.locator('.text-line-gutter')).toHaveCount(0);await expect(a.getByLabel('显示行号',{exact:true})).toBeDisabled();await expect(tb).toHaveAttribute('wrap','off');await a.getByLabel('自动换行',{exact:true}).uncheck();await expect(a.locator('.text-line-gutter')).toBeVisible();
  expect((await first.request.put(baseURL+'/api/cloud/document-permissions?workspace='+space.id,{data:{doc:resource.id,user:member.id,role:'viewer'}})).ok()).toBe(true);await expect(tb).toHaveAttribute('readonly','');await b.getByRole('button',{name:'文本格式',exact:true}).click();await expect(b.getByLabel('自动换行',{exact:true})).toBeEnabled();await b.getByLabel('自动换行',{exact:true}).check();await expect(b.getByLabel('文本编码',{exact:true})).toBeDisabled();
  await ta.fill('中文😀'.repeat(400)+'\n末尾');await b.setViewportSize({width:390,height:844});await b.getByLabel('自动换行',{exact:true}).uncheck();expect(await b.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth)).toBe(true);await tb.scrollIntoViewIfNeeded();await b.screenshot({path:'artifacts/txt-lines-mobile.png'});
 }finally{await first.close();await second.close();}
});

