  await a.getByRole('button',{name:'文本格式',exact:true}).click();await a.getByLabel('自动换行',{exact:true}).check();await expect(a.locator('.text-line-gutter')).toHaveCount(0);await expect(a.getByRole('group',{name:'文本协作成员',exact:true})).toBeVisible();
  await b.setViewportSize({width:390,height:844});expect(await b.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth)).toBe(true);await b.screenshot({path:'artifacts/txt-presence-mobile.png'});
  await a.getByRole('navigation',{name:'文档列表'}).getByRole('button',{name:'另一个.txt',exact:true}).click();await expect(members.getByRole('button',{name:/owner ·/})).toHaveCount(0);await a.getByRole('navigation',{name:'文档列表'}).getByRole('button',{name:'在线.txt',exact:true}).click();await ta.focus();await ta.evaluate(el=>(el as HTMLTextAreaElement).setSelectionRange(4,6));await expect(members.getByRole('button',{name:/owner ·/})).toBeVisible();
